import { decodePng } from '@styld/imaging'
import * as Base64 from 'effect/encoding/Base64'
import { Result } from 'effect'

// The wooden hanger every turn shows its garment on: an empty natural-wood hanger without a hook, drawn by Meta Muse
// Image on flat green for the hanger-rail proof (`meta-hackathon/out/styld-hanger-rail`, anchors/hanger-raw.png and
// prompts-hanger.txt, 30 October), keyed with the starter's matte and scaled to 600 pixels wide.
const png =
  ''

/** The hanger as transparent pixels. */
export const hanger = () => decodePng(Result.getOrElse(Base64.decode(png), () => new Uint8Array()))
